'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const token=new URLSearchParams(location.search).get('token')||sessionStorage.arenaToken||'';sessionStorage.arenaToken=token;
const state={tid:null,engines:[],selected:new Set(),gameSelected:new Set(),engOffset:0,gameOffset:0,standOffset:0,engineTotal:0,libraryTotal:0,gameTotal:0,standTotal:0,flip:false,snapshot:null,live:[],presets:[],view:'overview'};
let enginesGeneration=0,engineSearchTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>esc(ArenaFormat.number(v,d));
const profileResource=(p,name,fallback)=>Object.entries(p.options||{}).find(([k])=>k.toLowerCase()===name)?.[1]??p[name]??fallback;
const tcText=t=>!t?'Tournament default':t.kind==='nodes'?`${t.nodes.toLocaleString()} nodes / move`:t.kind==='depth'?`Depth ${t.depth}`:t.kind==='movetime'?`${t.seconds}s / move`:t.kind==='staged'?`${t.stages.length} stages${t.repeat?' · repeat':''}`:`${t.seconds}s${t.kind==='fischer'?' + '+t.increment+'s':t.kind.includes('delay')||t.kind==='bronstein'?' · '+t.delay+'s delay':''}`;
function statisticsQuery(){return new URLSearchParams({confidence:state.confidence||95,method:state.ciMethod||'normal',sort:state.standSort||'rank',direction:state.standDirection||'asc'}).toString()}
function ciText(s){const ci=state.ciMethod==='conservative'?(s.confidence!==undefined?s.ci_conservative:s.ci95_conservative):(s.confidence!==undefined?s.ci:s.ci95);return ci?ci.map(x=>fmt(x)).join(' to '):'—';}
function pct(v){return esc(ArenaFormat.percent(v));}
function stableHtml(selector,html){const el=$(selector);if(el._renderedHtml!==html){el.innerHTML=html;el._renderedHtml=html;}}
let noticeTimer;
function notify(text,error=false){
 if(error&&$('#modal').open){let inline=$('#modal .dialog-error');if(!inline){inline=document.createElement('div');inline.className='dialog-error';inline.setAttribute('role','alert');$('#modal .modal-head').after(inline)}inline.textContent=text;inline.hidden=!text;if(text!==state.workerError)return}
 const el=$(error?'#error':'#notice');el.textContent=text;el.hidden=!text;
 if(!error){clearTimeout(noticeTimer);if(text)noticeTimer=setTimeout(()=>el.hidden=true,8000)}
}
async function api(path,body){if(body===undefined&&/^tournaments\/[^/?]+(?:$|[?]|\/(?:h2h|crosstable|ratings|series|report)(?:[/?]|$))/.test(path)&&!/[?&]confidence=/.test(path))path+=(path.includes('?')?'&':'?')+'confidence='+(state.confidence||95);let r;try{r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'X-Arena-Token':token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})}catch{throw Error('The local worker is not responding. Check Worker & recovery, or reopen the application to recover saved games.')}if(!r.headers.get('content-type')?.includes('application/json'))throw Error(r.status===403?'The local session has expired. Reopen the application to reconnect.':'The worker returned an unexpected response ('+r.status+'). Check Worker & recovery.');const v=await r.json();if(!r.ok||v.error)throw Error(v.error||'Request failed');return v}
function safely(fn){let pending=false;return async(...a)=>{const button=a[0]?.currentTarget instanceof HTMLButtonElement?a[0].currentTarget:null,disabled=button?.disabled;if(button&&pending)return;try{if(button){pending=true;button.disabled=true;button.setAttribute('aria-busy','true')}await fn(...a)}catch(e){notify(e.message,true)}finally{if(button){pending=false;button.disabled=disabled;button.removeAttribute('aria-busy')}}}}
function download(name,text,type='application/json'){if(window.chrome?.webview){window.chrome.webview.postMessage({type:'download',name,text});return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportUrl(fmt){if(state.tid)window.open(`/api/export/${state.tid}/${fmt}?${statisticsQuery()}&token=${encodeURIComponent(token)}`,'_blank')}
function view(name){state.view=name;$$('.view').forEach(e=>e.hidden=e.id!==name);$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.view===name));$('#breadcrumb').textContent=name.toUpperCase();$('#pageTitle').textContent={overview:'Tournament workspace',engines:'Engine library',presets:'Test conditions',health:'Worker & recovery'}[name];if(name==='engines')safely(loadEngines)();if(name==='presets')safely(loadPresets)()}
$$('.nav').forEach(e=>e.onclick=()=>view(e.dataset.view));$('#theme').onclick=()=>{document.body.classList.toggle('light');localStorage.arenaTheme=document.body.classList.contains('light')?'light':'dark'};if(localStorage.arenaTheme==='light')document.body.classList.add('light');
function modal(title,body,footer=''){ $('#modalContent').innerHTML=`<div class="modal-head"><h2 id="dialogTitle">${esc(title)}</h2><span class="spacer"></span><button class="subtle" data-close aria-label="Close dialog">✕</button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer}<button data-close>Close</button></div>`;$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());$('#modal').setAttribute('aria-labelledby','dialogTitle');if(!$('#modal').open)$('#modal').showModal() }
const nativePending=new Map();let nativeId=0;
document.addEventListener('dragover',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();e.dataTransfer.dropEffect='copy'}});
document.addEventListener('drop',e=>{if(!e.dataTransfer?.files.length)return;e.preventDefault();const files=[...e.dataTransfer.files].filter(f=>f.name.toLowerCase().endsWith('.exe'));if(!files.length){notify('Drop UCI engine executables (.exe).',true);return}if(window.chrome?.webview?.postMessageWithAdditionalObjects)window.chrome.webview.postMessageWithAdditionalObjects({type:'droppedFiles'},files);else notify('Use Add executable to select the engine path.',true)});
window.chrome?.webview?.addEventListener('message',e=>{const m=e.data;if(m.type==='downloaded'){notify('Saved '+m.name);}else if(m.type==='paths'){view('engines');scanPaths(m.paths)}else if(nativePending.has(m.id)){nativePending.get(m.id)(m.paths||[]);nativePending.delete(m.id)}});
async function browse(folder=false,multiple=false,filter='All files|*.*'){
 if(window.chrome?.webview){return new Promise(resolve=>{const id=++nativeId;nativePending.set(id,resolve);window.chrome.webview.postMessage({type:'browse',id,folder,multiple,filter})})}
 const path=prompt(folder?'Folder path':'File path');return path?[path]:[];
}
function field(id,label,value,type='text',attrs=''){return `<div class="field"><label for="${id}">${esc(label)}</label><input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function pathField(id,label,value,folder=false){return `<div class="field full"><label for="${id}">${esc(label)}</label><div class="path"><input id="${id}" value="${esc(value)}"><button data-browse="${id}" data-folder="${folder}">Browse…</button></div></div>`}
function wireBrowsers(){$$('[data-browse]').forEach(b=>b.onclick=safely(async()=>{const p=await browse(b.dataset.folder==='true');if(p[0])$('#'+b.dataset.browse).value=p[0]}))}
function tcEditor(prefix,tc={kind:'fischer',seconds:180,increment:2,nodes:10000,depth:12,delay:0}){
 return `<div class="tc-editor" id="${prefix}"><div class="field"><label>Control</label><select data-tc="kind">${[['sudden_death','Sudden death'],['fischer','Fischer increment'],['delay','Simple delay'],['bronstein','Bronstein delay'],['staged','Staged / repeating'],['movetime','Fixed time per move'],['depth','Fixed depth'],['nodes','Pure nodes per move']].map(([v,t])=>`<option value="${v}" ${tc.kind===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field" data-for="sudden_death fischer delay bronstein movetime"><label>Seconds</label><input data-tc="seconds" type="number" min="0.001" step="any" value="${tc.seconds??180}"></div><div class="field" data-for="fischer"><label>Increment (seconds)</label><input data-tc="increment" type="number" min="0" step="any" value="${tc.increment??2}"></div><div class="field" data-for="delay bronstein"><label>Delay (seconds)</label><input data-tc="delay" type="number" min="0" step="any" value="${tc.delay??1}"></div><div class="field" data-for="nodes"><label>Nodes per move · no chess clock</label><input data-tc="nodes" type="number" min="1" step="1" value="${tc.nodes??10000}"></div><div class="field" data-for="depth"><label>Search depth (plies)</label><input data-tc="depth" type="number" min="1" value="${tc.depth??12}"></div><div class="stages" data-for="staged"><div class="stage-list">${(tc.stages?.length?tc.stages:[{moves:40,seconds:120,increment:0},{moves:0,seconds:60,increment:1}]).map(stageRow).join('')}</div><button class="add-stage" type="button">＋ Stage</button> <label><input data-tc="repeat" type="checkbox" ${tc.repeat?'checked':''}> Repeat final stage</label><small>Moves = 0 means final sudden death.</small></div></div>`;
}
function stageRow(s){return `<div class="stage-row"><input data-stage="moves" type="number" min="0" value="${s.moves}" aria-label="Stage moves"> moves / <input data-stage="seconds" type="number" min="0.001" step="any" value="${s.seconds}" aria-label="Stage seconds"> sec + <input data-stage="increment" type="number" min="0" step="any" value="${s.increment??0}" aria-label="Stage increment"> sec <button class="remove-stage">✕</button></div>`}
function wireTc(prefix){const root=$('#'+prefix);const update=()=>{const kind=root.querySelector('[data-tc=kind]').value;root.querySelectorAll('[data-for]').forEach(e=>e.hidden=!e.dataset.for.split(' ').includes(kind))};root.querySelector('[data-tc=kind]').onchange=update;root.querySelector('.add-stage').onclick=()=>{root.querySelector('.stage-list').insertAdjacentHTML('beforeend',stageRow({moves:40,seconds:60,increment:0}));wireRemove()};const wireRemove=()=>root.querySelectorAll('.remove-stage').forEach(b=>b.onclick=()=>b.closest('.stage-row').remove());wireRemove();update()}
function readTc(prefix){const root=$('#'+prefix),kind=root.querySelector('[data-tc=kind]').value,t={kind};const fields={sudden_death:['seconds'],fischer:['seconds','increment'],delay:['seconds','delay'],bronstein:['seconds','delay'],movetime:['seconds'],nodes:['nodes'],depth:['depth'],staged:[]};for(const key of fields[kind])t[key]=Number(root.querySelector(`[data-tc=${key}]`).value);if(kind==='staged'){t.repeat=root.querySelector('[data-tc=repeat]').checked;t.stages=[...root.querySelectorAll('.stage-row')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-stage]')].map(e=>[e.dataset.stage,Number(e.value)])))}return t}
async function loadEngines(){const query=$('#engineSearch').value,offset=state.engOffset,generation=++enginesGeneration;const r=await api(`profiles?q=${encodeURIComponent(query)}&offset=${offset}&limit=50`);if(generation!==enginesGeneration||query!==$('#engineSearch').value||offset!==state.engOffset)return;state.engines=r.items;state.engineTotal=r.total;state.libraryTotal=r.library_total;$('#engineCount').textContent=r.library_total.toLocaleString();$('#enginePage').textContent=`${r.total?state.engOffset+1:0}–${Math.min(state.engOffset+50,r.total)} of ${r.total.toLocaleString()}`;$('#selectedCount').textContent=`${state.selected.size} selected`;stableHtml('#engineTable tbody',r.items.map(p=>`<tr><td><input type="checkbox" aria-label="Select ${esc(p.name)}" data-engine="${p.id}" ${state.selected.has(p.id)?'checked':''}></td><td><b>${esc(p.name)}</b><small>${esc(p.identity?.name||'Identity not yet tested')}</small></td><td>${profileResource(p,'threads',1)}</td><td>${profileResource(p,'hash',1024)} MB</td><td>${esc(tcText(p.time_control))}</td><td class="path-cell" title="${esc(p.path)}">${esc(p.path)}</td><td><button data-edit="${p.id}" class="subtle">Configure</button><button data-delete-engine="${p.id}" class="danger-quiet" aria-label="Delete ${esc(p.name)}" data-help="Remove this profile from the library. The executable and saved tournament records are kept.">Delete…</button></td></tr>`).join(''));$$('[data-engine]').forEach(e=>e.onchange=()=>{e.checked?state.selected.add(e.dataset.engine):state.selected.delete(e.dataset.engine);$('#selectedCount').textContent=`${state.selected.size} selected`});$$('[data-edit]').forEach(e=>e.onclick=()=>editEngine(state.engines.find(p=>p.id===e.dataset.edit)));}
function optionsHtml(profile){return Object.values(profile.advertised||{}).map(o=>{const v=profile.options?.[o.name]??o.default;let control=o.type==='check'?`<input type="checkbox" ${v?'checked':''}>`:o.type==='combo'?`<select>${o.var.map(s=>`<option ${s===v?'selected':''}>${esc(s)}</option>`).join('')}</select>`:o.type==='button'?`<input type="checkbox"> Apply on connection`:`<input type="${o.type==='spin'?'number':'text'}" value="${esc(v??'')}" ${o.min!==null?`min="${o.min}"`:''} ${o.max!==null?`max="${o.max}"`:''}>`;return `<div class="option" data-option="${esc(o.name)}" data-type="${o.type}"><label>${esc(o.name)}</label>${control}<small>${o.type==='spin'?`Range ${o.min}–${o.max} · `:''}Default: ${esc(o.default??'button')}</small>${o.type==='string'?'<button class="option-file subtle">File…</button><button class="option-folder subtle">Folder…</button>':''}</div>`}).join('')}
function editEngine(profile={path:'',name:'',args:[],threads:1,hash:1024}){
 modal(profile.id?'Configure engine profile':'Add UCI engine',`<div class="fields">${pathField('epath','Engine executable',profile.path)}${field('ename','Profile name',profile.name)}${field('eargs','Launch arguments (quoted paths supported)',Array.isArray(profile.args)?profile.args.map(a=>a.includes(' ')?'"'+a+'"':a).join(' '):profile.args||'')}${pathField('ecwd','Working directory (blank = executable folder)',profile.cwd||'',true)}${field('ethreads','CPU threads',profile.threads??1,'number','min="1"')}${field('ehash','Hash memory (MB per engine)',profile.hash??1024,'number','min="1"')}${field('eaffinity','CPU affinity (comma-separated logical CPU numbers)',(profile.affinity||[]).join(','))}${field('egpu','Shared GPU group (blank = CPU only)',profile.gpu_group||'')}${field('eextra','Additional memory per engine (MB)',profile.extra_memory_mb??256,'number','min="0"')}<div class="field"><label><input id="eindependent" type="checkbox" ${profile.time_control?'checked':''}> Independent time control / handicap</label></div></div><div id="engineTc" ${profile.time_control?'':'hidden'}><div class="section-label">ENGINE TIME CONTROL</div>${tcEditor('etc',profile.time_control)}</div><div class="section-label">ADVERTISED UCI OPTIONS</div><p class="caption">Test connection discovers the engine name, version and every advertised option. Threads and Hash stay synchronized with the resource fields above.</p><div class="options">${optionsHtml(profile)}</div>`,`<button id="testEngine">Test connection & discover</button><button class="primary" id="saveEngine">Save profile</button>`);wireBrowsers();wireTc('etc');$('#eindependent').onchange=()=>$('#engineTc').hidden=!$('#eindependent').checked;
 for(const [name,id] of [['threads','ethreads'],['hash','ehash']]){const option=$$('[data-option]').find(el=>el.dataset.option.toLowerCase()===name),resource=$('#'+id);if(!option)continue;const input=option.querySelector('input'),key=option.dataset.option;resource.value=profile.options?.[key]??profile[name]??input.value;input.value=resource.value;resource.oninput=()=>input.value=resource.value;input.oninput=()=>resource.value=input.value}
 const read=()=>{const p={...profile,path:$('#epath').value.trim(),name:$('#ename').value.trim(),args:$('#eargs').value,cwd:$('#ecwd').value.trim(),threads:Number($('#ethreads').value),hash:Number($('#ehash').value),affinity:$('#eaffinity').value.split(',').filter(v=>v.trim()).map(Number),gpu_group:$('#egpu').value.trim(),extra_memory_mb:Number($('#eextra').value),options:{}};if($('#eindependent').checked)p.time_control=readTc('etc');else delete p.time_control;$$('[data-option]').forEach(el=>{const input=el.querySelector('input,select'),kind=el.dataset.type;if(kind==='button'&&!input.checked)return;p.options[el.dataset.option]=kind==='button'?null:kind==='check'?input.checked:kind==='spin'?Number(input.value):input.value});return p};
 $('#testEngine').onclick=safely(async()=>{const b=$('#testEngine');b.disabled=true;b.textContent='Connecting…';try{const p=await api('profiles/discover',read());if(!b.isConnected||!$('#modal').open)return;editEngine(p);notify('Connection verified. Review the discovered options, then Save profile.')}finally{b.disabled=false;b.textContent='Test connection & discover'}});
 $('#saveEngine').onclick=safely(async()=>{const p=await api('profiles',{...read(),discover:!profile.advertised});state.selected.add(p.id);$('#modal').close();await loadEngines();notify('Engine profile saved.')});
 $$('.option-file,.option-folder').forEach(b=>b.onclick=safely(async()=>{const p=await browse(b.classList.contains('option-folder'));if(p[0])b.parentElement.querySelector('input').value=p[0]}));
}
async function scanPaths(paths){notify('Discovering UCI executables…');const r=await api('scan',{paths});await loadEngines();notify(r.items.map(x=>x.error?`${x.path}: ${x.error}`:`Added ${x.profile.name}`).join('\n'),r.items.some(x=>x.error))}
$('#addEngine').onclick=()=>editEngine();$('#emptyAdd').onclick=()=>{view('engines');editEngine()};$('#engineSearch').oninput=()=>{state.engOffset=0;clearTimeout(engineSearchTimer);engineSearchTimer=setTimeout(safely(loadEngines),150)};$('#engPrev').onclick=safely(async()=>{state.engOffset=Math.max(0,state.engOffset-50);await loadEngines()});$('#engNext').onclick=safely(async()=>{if(state.engOffset+50<state.engineTotal)state.engOffset+=50;await loadEngines()});
$('#scanFolder').onclick=safely(async()=>{const p=await browse(true);if(p[0]){notify('Scanning executables in folder…');const r=await api('scan',{folder:p[0]});await loadEngines();notify(r.items.map(x=>x.error?`${x.path}: ${x.error}`:`Added ${x.profile.name}`).join('\n'),r.items.some(x=>x.error))}});
$('#cloneEngine').onclick=safely(async()=>{const all=(await api('profiles?limit='+state.libraryTotal)).items;for(const p of all.filter(p=>state.selected.has(p.id))){const clone={...p,name:p.name+' (copy)',discover:false};delete clone.id;await api('profiles',clone)}await loadEngines()});
$('#bulkEngine').onclick=()=>{modal('Bulk resource settings',`<p>Apply to ${state.selected.size} selected profiles.</p><div class="fields">${field('bulkThreads','CPU threads',1,'number','min="1"')}${field('bulkHash','Hash MB',1024,'number','min="1"')}</div>`,`<button class="primary" id="applyBulk">Apply</button>`);$('#applyBulk').onclick=safely(async()=>{const all=(await api('profiles?limit='+state.libraryTotal)).items;for(const p of all.filter(p=>state.selected.has(p.id))){p.threads=Number($('#bulkThreads').value);p.hash=Number($('#bulkHash').value);for(const key of Object.keys(p.options||{})){if(key.toLowerCase()==='threads')p.options[key]=p.threads;if(key.toLowerCase()==='hash')p.options[key]=p.hash}await api('profiles',{...p,discover:false})}$('#modal').close();await loadEngines()})};
$('#exportEngines').onclick=safely(async()=>download('engine-profiles.json',JSON.stringify((await api('profiles?limit='+state.libraryTotal)).items,null,2)));$('#importEngines').onclick=()=>$('#jsonFile').click();$('#jsonFile').onchange=safely(async e=>{const f=e.target.files[0];if(f){await api('profiles/import',{profiles:JSON.parse(await f.text())});await loadEngines()}e.target.value=''});
async function loadPresets(){state.presets=await api('presets');$('#presetList').innerHTML=state.presets.map(p=>`<article class="preset"><h3>${esc(p.name)}</h3><p>${esc(tcText(p.settings.time_control))}<br>${p.settings.threads??1} thread(s) · ${p.settings.hash??1024} MB hash<br>${p.settings.paired?'Paired openings':'Single games'}</p></article>`).join('')}
$('#savePreset').onclick=()=>{modal('Save a reusable preset',`${field('presetName','Preset name','My control')}${tcEditor('ptc')}<div class="fields">${field('pThreads','Threads',1,'number','min="1"')}${field('pHash','Hash MB',1024,'number','min="1"')}<label><input id="pPaired" type="checkbox" checked> Paired openings</label></div>`,`<button class="primary" id="saveP">Save preset</button>`);wireTc('ptc');$('#saveP').onclick=safely(async()=>{await api('presets',{name:$('#presetName').value,settings:{time_control:readTc('ptc'),threads:Number($('#pThreads').value),hash:Number($('#pHash').value),paired:$('#pPaired').checked,ponder:false}});$('#modal').close();await loadPresets()})};
function countGames(n,f,c,p,r,ca){let pairs;if(['match','sprt'].includes(f))pairs=c;else if(f==='self_play')pairs=n*c;else if(f==='round_robin')pairs=n*(n-1)/2*c;else if(f==='gauntlet')pairs=ca*(n-ca)*c;else if(f==='knockout')pairs=(n-1)*c;else if(f==='double_elimination')pairs=(2*n-2)*c;else pairs=Math.floor(n/2)*r*c;return pairs*(p?2:1)}
