function boardHtml(fen,last='',flip=state.flip){
 const cells=[];for(const row of fen.split(' ')[0].split('/'))for(const c of row){if(/[1-8]/.test(c))for(let n=0;n<Number(c);n++)cells.push('');else cells.push(c)}
 const order=[...Array(64).keys()];if(flip)order.reverse();
 return `<div class="board" data-flip="${flip}">${order.map(i=>{const rank=8-Math.floor(i/8),file='abcdefgh'[i%8],sq=file+rank,p=cells[i];return `<div data-square="${sq}" class="square ${(Math.floor(i/8)+i%8)%2?'dark':''} ${last.includes(sq)?'highlight':''}">${p?`<img draggable="false" alt="${p===p.toUpperCase()?'White':'Black'} ${ {K:'king',Q:'queen',R:'rook',B:'bishop',N:'knight',P:'pawn'}[p.toUpperCase()]}" src="/pieces/${state.pieceSet||'classic'}/${p===p.toUpperCase()?'w':'b'}${p.toUpperCase()}.svg">`:''}${(flip?rank===8:rank===1)?`<span class="coord">${file}</span>`:''}</div>`}).join('')}<svg class="board-arrows" viewBox="0 0 800 800" aria-hidden="true"></svg></div>`;
}
function clockFace(g,side){return `<div class="clock-face" data-clock-game="${g.game}" data-clock-side="${side}"><span class="clock-name">${side==='white'?'White':'Black'}${g[side]?.name?' · '+esc(g[side].name):''}</span><strong class="clock-time"></strong><small class="clock-caption"></small></div>`}
function paintClock(el,g,side,age=0){const c=ArenaClocks.project(g,side,age);el.classList.toggle('thinking',c.active);el.classList.toggle('stale',c.stale);const value=el.querySelector('.clock-time'),caption=el.querySelector('.clock-caption');if(value.textContent!==c.text)value.textContent=c.text;const text=c.label+(c.detail?' · '+c.detail:'');if(caption.textContent!==text)caption.textContent=text;el.title=(side==='white'?'White':'Black')+': '+c.text+' · '+text;}
function paintLiveClocks(){const live=new Map(state.live.map(g=>[g.game,g]));for(const el of $$('[data-clock-game]')){const g=live.get(el.dataset.clockGame);if(g)paintClock(el,g,el.dataset.clockSide,performance.now()-(g.receivedAt||performance.now()));}}
setInterval(()=>{if(!document.hidden)paintLiveClocks()},100);
function updateBoard(host,fen,last=''){
 let board=host.querySelector('.board');
 if(!board||board.dataset.flip!==String(state.flip)||board.dataset.pieces!==(state.pieceSet||'classic')){host.innerHTML=boardHtml(fen,last);board=host.querySelector('.board');board.dataset.pieces=state.pieceSet||'classic';board.dataset.fen=fen;board.dataset.last=last;return}
 if(board.dataset.fen===fen&&board.dataset.last===last)return;
 const pieces={};fen.split(' ')[0].split('/').forEach((row,r)=>{let f=0;for(const c of row){if(/[1-8]/.test(c))f+=Number(c);else pieces['abcdefgh'[f++]+(8-r)]=c}});
 for(const square of board.querySelectorAll('[data-square]')){const p=pieces[square.dataset.square],old=square.querySelector('img');square.classList.toggle('highlight',last.includes(square.dataset.square));if(!p){old?.remove();continue}const name=(p===p.toUpperCase()?'w':'b')+p.toUpperCase(),src=`/pieces/${state.pieceSet||'classic'}/${name}.svg`;if(old?.getAttribute('src')===src)continue;const img=old||document.createElement('img');img.src=src;img.draggable=false;img.alt=(p===p.toUpperCase()?'White ':'Black ')+{K:'king',Q:'queen',R:'rook',B:'bishop',N:'knight',P:'pawn'}[p.toUpperCase()];if(!old)square.prepend(img)}
 board.dataset.fen=fen;board.dataset.last=last;board.querySelector('.board-arrows')?.replaceChildren();
}
function renderBoards(){
 const root=$('#liveBoards'),active=state.live.filter(g=>g.tid===state.tid),games=active.slice(0,Number($('#boardCount').value));
 $('#liveBoardSummary').textContent=`Showing ${games.length} of ${active.length} active games · display only; concurrency is unchanged.`;
 const wanted=new Set(games.map(g=>g.game)),cards=new Map([...root.querySelectorAll('[data-livegame]')].map(card=>[card.dataset.livegame,card]));
 for(const [id,card] of cards)if(!wanted.has(id))card.remove();
 if(!games.length){if(!root.querySelector('.caption'))root.innerHTML='<p class="caption">No active games. Standings and history remain available.</p>';if(typeof renderFocus==='function')renderFocus();return}
 root.querySelector('.caption')?.remove();
 for(const [index,g] of games.entries()){
  let card=cards.get(g.game);
  if(!card){card=document.createElement('article');card.className='board-card';card.dataset.livegame=g.game;card.innerHTML=clockFace(g,'black')+'<div class="board-host"></div>'+clockFace(g,'white')+'<small class="game-status"></small>';card.onclick=safely(event=>{if(event.button===0&&!event.defaultPrevented)gameDetail(g.game)})}
  if(root.children[index]!==card)root.insertBefore(card,root.children[index]||null);

  card.querySelector('.game-status').textContent=`Game ${g.number+1} · ${g.status} · ${g.ply} ply`;
  updateBoard(card.querySelector('.board-host'),g.fen,g.last_move);
  if(typeof paintEvaluation==='function')paintEvaluation(card.querySelector('.board-host'),g,'live');
 }
 if(typeof renderFocus==='function')renderFocus();
 paintLiveClocks();
}
$('#boardCount').value=localStorage.arenaBoards||'2';$('#boardCount').onchange=()=>{localStorage.arenaBoards=$('#boardCount').value;renderBoards()};$('#flipBoards').onclick=()=>{state.flip=!state.flip;renderBoards()};
function movePrefix(fen,index){const fields=fen.split(' '),black=fields[1]==='b',number=Number(fields[5]||1)+Math.floor((index+(black?1:0))/2);return (index+(black?1:0))%2===0?number+'. ':index===0?number+'… ':''}
async function gameDetail(id){const g=await api('games/'+id);modal(`Game ${g.number+1} · opening pair ${g.pair_no+1}`,`<div class="replay-layout"><div><div id="replayClocks" class="focus-clocks"></div><div id="replayBoard"></div></div><div><label>Attempt <select id="attemptPicker">${g.attempts.map((a,i)=>`<option value="${i}" ${i===g.attempts.length-1?'selected':''}>${a.seq} · ${a.mode} · ${a.reason||'running'} ${g.official===a.id?'· OFFICIAL':''}</option>`).join('')}</select></label><p id="attemptResult"></p><div class="toolbar"><button id="replayFirst">|←</button><button id="replayBack">←</button><span id="replayPly"></span><button id="replayForward">→</button><button id="replayLast">→|</button></div><div class="move-list" id="moveList"></div><select id="graphMetric"><option value="cp">Evaluation (cp, White perspective)</option><option value="depth">Depth (plies)</option><option value="nodes">Nodes</option><option value="nps">Nodes / second</option><option value="time">Reported search time (ms)</option><option value="hashfull">Hash occupancy (per mille)</option><option value="tbhits">Tablebase hits</option><option value="elapsed">Move elapsed time (s)</option></select><div id="moveGraph"></div></div></div><p class="caption">${esc(g.opening.name||'Opening')} · FEN ${esc(g.opening.fen)}</p><details><summary>UCI diagnostics (recent 300 lines)</summary><pre class="log" id="attemptLogs"></pre></details>`);let attempt=g.attempts.at(-1),ply=attempt?.moves.length||0;const render=()=>{const recorded=ply?attempt.moves[ply-1].clocks:null;if(recorded){const clocks=typeof recorded==='string'?JSON.parse(recorded):recorded;$('#replayClocks').innerHTML=clockFace({game:g.id},'white')+clockFace({game:g.id},'black');for(const el of $$('#replayClocks .clock-face')){el.removeAttribute('data-clock-game');paintClock(el,{clocks},el.dataset.clockSide)}}else $('#replayClocks').innerHTML='<small class="caption">Clocks recorded after each move</small>';$('#replayBoard').innerHTML=boardHtml(ply?attempt.moves[ply-1].fen:g.opening.fen,ply?attempt.moves[ply-1].uci:'');$('#replayPly').textContent=`${ply} / ${attempt?.moves.length||0}`;$('#attemptResult').textContent=attempt?`${attempt.result||'In progress'} · ${attempt.reason||'Running'} · ${attempt.detail||''}`:'Not started';$('#moveList').innerHTML=(attempt?.moves||[]).map((m,i)=>`<button data-ply="${i+1}" ${i+1===ply?'class="primary"':''}>${movePrefix(g.opening.fen,i)}${esc(m.san)}</button>`).join('');$$('[data-ply]').forEach(b=>b.onclick=()=>{ply=Number(b.dataset.ply);render()});$('#attemptLogs').textContent=(attempt?.logs||[]).slice().reverse().map(x=>x.line).join('\n');renderGraph(attempt?.moves||[])};$('#attemptPicker').onchange=()=>{attempt=g.attempts[Number($('#attemptPicker').value)];ply=attempt.moves.length;render()};$('#replayFirst').onclick=()=>{ply=0;render()};$('#replayLast').onclick=()=>{ply=attempt?.moves.length||0;render()};$('#replayBack').onclick=()=>{ply=Math.max(0,ply-1);render()};$('#replayForward').onclick=()=>{ply=Math.min(attempt?.moves.length||0,ply+1);render()};$('#graphMetric').onchange=()=>renderGraph(attempt?.moves||[]);render()}
function renderGraph(moves){const key=$('#graphMetric').value,values=moves.map((m,i)=>[i,key==='elapsed'?m.elapsed:JSON.parse(m.info)[key]]).filter(x=>Number.isFinite(x[1]));if(!values.length){$('#moveGraph').innerHTML='<p class="caption">No reported data for this metric.</p>';return}const lo=Math.min(...values.map(v=>v[1])),hi=Math.max(...values.map(v=>v[1]));const points=values.map(([i,v])=>`${35+450*i/Math.max(1,moves.length-1)},${105-85*(v-lo)/Math.max(1,hi-lo)}`).join(' ');$('#moveGraph').innerHTML=`<svg class="graph" viewBox="0 0 500 130" role="img" aria-label="${esc(key)} by ply"><text x="3" y="15" fill="var(--muted)" font-size="9">${fmt(hi)}</text><text x="3" y="110" fill="var(--muted)" font-size="9">${fmt(lo)}</text><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2"/><text x="240" y="125" fill="var(--muted)" font-size="9">Ply →</text></svg>`}
$('#retrySaving').onclick=safely(async()=>{await api('retry-saving',{});notify('Storage and PGN checks passed. Resume the tournament when ready.');$('#error').hidden=true});
let refreshing=false,tick=0;
async function refresh(){if(refreshing)return;refreshing=true;try{const s=await api('status');state.live=s.live.map(g=>({...g,receivedAt:performance.now()}));if(typeof recordHardware==='function')recordHardware(s);$('#sideStatus').textContent=`${s.active_games} active games · ${s.logical_cpus} logical CPUs`;if(typeof renderHardware==='function')renderHardware(s);state.connected=true;if(typeof renderWorkerHealth==='function')renderWorkerHealth(s);if(s.error)notify(s.error,true);if(state.tid){renderBoards();if(tick++%2===0)await refreshTournament()}}catch(e){state.connected=false;if(typeof hardwareDisconnected==='function')hardwareDisconnected();$('#sideStatus').textContent='Worker connection lost — saved results retained';notify(e.message,true)}finally{refreshing=false}}
safely(async()=>{await loadEngines();await loadTournaments();await refresh();setInterval(refresh,750)})();

// Test suites share the worker queue and use immutable engine/case snapshots.
const experimentNav=document.createElement('button');experimentNav.className='nav';experimentNav.dataset.view='experiments';experimentNav.innerHTML='◇ <span>Suites & benchmarks</span>';$('nav').insertBefore(experimentNav,$('[data-view=health]'));
const experimentView=document.createElement('section');experimentView.id='experiments';experimentView.className='view';experimentView.hidden=true;experimentView.innerHTML=`<div class="toolbar"><button class="primary" id="newSuite">＋ EPD test suite</button><button id="newBenchmark">＋ Thread-scaling benchmark</button><button id="refreshExperiments">Refresh</button><span class="muted">Uses profiles selected in Engine library. Experiments run after queued tournaments.</span></div><div class="panel"><div class="panel-title"><h2>Reproducible experiments</h2></div><div id="experimentList"></div></div>`;$('main').appendChild(experimentView);
experimentNav.onclick=safely(async()=>{view('experiments');$('#pageTitle').textContent='Suites & benchmarks';await loadExperiments()});
async function loadExperiments(){const jobs=await api('experiments');if(!jobs.length){stableHtml('#experimentList','<div class="panel-empty"><h3>No experiments yet</h3><p>Select engine profiles in the library, then create an EPD suite or a thread-scaling benchmark.</p></div>');return}stableHtml('#experimentList',`<table><thead><tr><th>EXPERIMENT</th><th>TYPE</th><th>PROGRESS</th><th>STATE</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${esc(j.name)}</td><td>${esc(j.kind)}</td><td>${j.cursor} / ${j.total}</td><td>${esc(j.state)}</td><td><button data-exstart="${j.id}" ${j.state==='running'||j.state==='completed'?'disabled':''}>${j.state==='completed'?'Completed':'Start / resume'}</button> <button data-expause="${j.id}" ${j.state!=='running'?'disabled':''}>Pause & drain</button> <button data-exresults="${j.id}">Results</button></td></tr>`).join('')}</tbody></table>`);$$('[data-exstart]').forEach(b=>b.onclick=safely(async()=>{await api(`experiments/${b.dataset.exstart}/action`,{action:'start'});await loadExperiments()}));$$('[data-expause]').forEach(b=>b.onclick=safely(async()=>{await api(`experiments/${b.dataset.expause}/action`,{action:'pause'});await loadExperiments()}));$$('[data-exresults]').forEach(b=>b.onclick=safely(()=>experimentResults(b.dataset.exresults)))}
$('#refreshExperiments').onclick=safely(loadExperiments);
function newExperiment(kind){modal(kind==='suite'?'Create EPD best/avoid-move suite':'Create repeatable thread-scaling benchmark',`${field('exname','Experiment name',kind==='suite'?'EPD accuracy suite':'Thread-scaling benchmark')}<p class="caption">${state.selected.size} selected engine profiles. Each case and engine configuration is saved for reproducibility.</p>${kind==='suite'?pathField('expath','EPD file with bm and/or am operations',''):`<div class="fields">${field('exthreads','Thread counts (comma separated)','1,2,4,8')}${field('exrepeats','Repeats per thread count',3,'number','min="1"')}<div class="full">${field('exfen','Benchmark FEN','rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')}</div></div>`}<div class="section-label">SEARCH LIMIT</div>${tcEditor('extc',{kind:'nodes',nodes:1000000,depth:16,seconds:1})}<p class="caption">Choose nodes, depth or fixed time per move. Benchmarks run one engine at a time. Reported nodes and wall elapsed time are recorded independently.</p>`,`<button id="createExperiment" class="primary">Create paused experiment</button>`);wireTc('extc');wireBrowsers();$('#createExperiment').onclick=safely(async()=>{if(!state.selected.size)throw Error('Select engine profiles in Engine library first.');const settings={time_control:readTc('extc')};if(kind==='benchmark'){settings.thread_counts=$('#exthreads').value.split(',').map(Number);settings.repeats=Number($('#exrepeats').value);settings.fen=$('#exfen').value}await api('experiments',{name:$('#exname').value,kind,profiles:[...state.selected],settings,path:kind==='suite'?$('#expath').value:undefined});$('#modal').close();await loadExperiments()})}
$('#newSuite').onclick=()=>newExperiment('suite');$('#newBenchmark').onclick=()=>newExperiment('benchmark');
async function experimentResults(id){const job=await api('experiments/'+id);modal(job.name,`<p>${job.completed} / ${job.total} cases completed${job.accuracy_pct===null?'':` · ${fmt(job.accuracy_pct)}% accuracy`}</p><p class="caption">Time to solve is the first matching reported PV in a search whose final move is correct. Interrupted attempts are retained and excluded from accuracy. Measured NPS = final reported nodes / wall search seconds; compare repeated samples under equal conditions.</p><div class="table-scroll"><table><thead><tr><th>ENGINE / CASE</th><th>THREADS</th><th>MOVE</th><th>ACCURACY</th><th>ELAPSED (s)</th><th>SOLVE (s)</th><th>MEASURED NPS</th><th>STATUS</th></tr></thead><tbody>${job.results.map(r=>`<tr><td>${esc(r.profile)}<small>${esc(r.case.id)}</small></td><td>${r.case.threads||profileResource(r.profile_snapshot,'threads',1)}</td><td>${esc(r.san||r.move||'—')}</td><td>${r.correct===undefined?'—':r.correct?'Correct':'Incorrect'}</td><td>${fmt(r.elapsed_seconds,4)}</td><td>${fmt(r.time_to_solve_seconds,4)}</td><td>${fmt(r.measured_nps,0)}</td><td>${esc(r.reason||'running')}${r.official?'':' · archived'}</td></tr>`).join('')}</tbody></table></div>`,`<button id="exportExperiment">Export JSON</button><button id="cancelExperiment">Stop current case</button>`);$('#exportExperiment').onclick=()=>download('experiment-'+id+'.json',JSON.stringify(job,null,2));$('#cancelExperiment').onclick=safely(async()=>{await api('experiments/'+id+'/action',{action:'cancel'});$('#modal').close();await loadExperiments()})}
setInterval(()=>{if(state.view==='experiments'&&!$('#modal').open)safely(loadExperiments)()},2000);
